from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent.parent
font='@font-face{font-family:SUIT;src:url(SUIT-Variable.woff2)}'
css=font+'''
*{box-sizing:border-box}body{margin:0;font-family:SUIT,'Apple SD Gothic Neo',sans-serif;color:#272b27}.device{position:relative;width:411px;height:881.38px;overflow:visible;background:#ebecee;border-radius:20px}.device>img{position:absolute;width:100%;height:100%;inset:0;border-radius:inherit}.layer{position:absolute}.pillbutton{height:44px;border:0;border-radius:12px;padding:0 18px;font:700 16px SUIT;background:#f9faf7;color:#304432;display:flex;align-items:center;justify-content:center;gap:8px}.primary{background:#36563c;color:white}.selection-actions{left:43px;top:207px;display:flex;gap:4px;padding:5px;background:#fff;border-radius:14px;box-shadow:0 3px 16px #27332922}.selection-actions .pillbutton{border-radius:10px}.expand{width:44px;height:44px;padding:0;border:1px solid #d9ddd8;background:#f5f5f3;color:#777d77;box-shadow:0 1px 3px #0002}.edit-area{left:0;top:81.714px;width:411px;height:358.86px;background:#ebecee;padding:8px}.paper{position:relative;background:#f8e9a4;border-radius:8px;height:100%;padding:12px;box-shadow:0 2px 8px #0001}.paper-head{display:flex;align-items:center;justify-content:space-between;height:44px;gap:8px}.paper-head strong{font-size:15px;color:#666143}.input-title{font-size:21px;font-weight:750;margin:28px 7px 20px;color:#3c3e32}.placeholder{font-size:16px;line-height:1.8;margin:0 7px;color:#797352}.caret{display:inline-block;height:21px;width:1.5px;background:#434635;vertical-align:-4px;margin-right:3px}.hint{position:absolute;bottom:18px;left:20px;font-size:12px;color:#68654e}.read-area{left:0;top:81.714px;width:411px;height:752.57px;background:#ebecee;padding:8px}.read-area .paper{display:flex;flex-direction:column}.read-head{flex:none;border-bottom:1px solid #6e693422;padding-bottom:8px;height:54px}.read-head .pillbutton{padding:0 12px;background:transparent}.read-head .primary{background:#36563c;color:#fff}.reading{flex:1;overflow:hidden;margin:16px 9px 4px;font-size:16px;line-height:1.6;color:#373a2d}.reading h3{font-size:16px;margin:0 0 18px}.reading p{margin:0 0 10px}.read-status{font-size:12px;color:#6d715f;padding:8px 9px 2px}.marker{position:absolute;outline:2px solid #ba4f42;outline-offset:3px;border-radius:7px;pointer-events:none;z-index:10}.marker.dashed{outline-style:dashed}.badge{position:absolute;top:-4px;left:-32px;width:25px;height:25px;border-radius:50%;background:#ba4f42;color:#fff;border:2px solid #fff;display:flex;align-items:center;justify-content:center;font:800 14px SUIT;box-shadow:0 1px 4px #0002}.marker.right .badge{left:auto;right:-32px}.label{font:750 20px SUIT}.screen-only{width:411px;height:881.38px}
'''
# Percentages were checked against asis.grid.png and cross-checked with measured DOM bounds.
asmarks=[[(1,10,16,80,6.6),(2,24.5,45.9,7.8,3.7)],[(3,34.5,43.3,42,4.8),(4,20,80,62,12)],[(5,1,57,98,36),(6,75,95,8,4)]]
tomarks=[[(1,10.5,23.5,65,6.1),(2,23,45.1,10.7,5)],[(3,5,17.8,90,26),(4,78,11.5,15,5)],[(5,77,10.8,16,5),(6,75,95,8,4)]]
scenes=[dict(key='a',title='기존 할 일도, 편집할 곳이 보여야 한다',action='같은 할 일 카드를 한 번 탭한 상태 · 캔버스 배율 71%',before=[('1','선택은 되지만 편집 진입이 없다','제목·항목은 읽기 전용.\n더블탭도 편집으로 이어지지 않았다.'),('2','축소하면 버튼도 작아진다','펼치기 버튼의 실제 터치 영역은\n약 32px였다.')],after=[('1','선택한 카드에 편집·이동을 표시','탭은 선택으로 유지한다.\n「편집」을 눌러 입력을 시작한다.'),('2','터치 영역은 화면 기준 44px','캔버스가 작아져도\n버튼을 누를 크기는 유지한다.')],foot='제안: 카드 종류마다 편집 버튼을 제공한다. 기존 할 일·메모의 내용과 캔버스 배치는 유지한다.'),dict(key='b',title='키보드가 떠도, 쓰기와 끝내기가 한 화면에',action='같은 입력: 도크의 「메모」를 누름 · 삼성 키보드가 열린 상태',before=[('3','캔버스 위 작은 제목칸에 입력','메모 아래가 키보드에 가려진다.\n입력 영역은 캔버스 배율을 따른다.'),('4','완료 수단이 보이지 않는다','도크와 줌은 키보드 뒤에 남는다.\nOS 뒤로가기로 키보드를 내려야 한다.')],after=[('3','새 메모는 바로 전용 편집 화면','제목과 본문을 한 자리에서 쓴다.\n키보드 높이에 맞춰 영역을 조절한다.'),('4','완료 버튼은 키보드 위에 고정','「완료」로 편집을 끝내고\n원래 보드로 돌아간다.')],foot='제안: 새 메모만 바로 편집한다. 기존 메모를 읽는 동작과 구분한다. 시안 문구는 예시다.'),dict(key='c',title='읽으러 열면 읽기, 뒤로가면 보드',action='같은 QA 메모 본문을 읽고 보드로 돌아가는 장면 · 본문 내용은 동일',before=[('5','상세에 들어가면 키보드가 열린다','자동 포커스로 읽을 공간이 줄고\n편집 상태부터 시작한다.'),('6','뒤로가기 두 번이면 Moss를 나간다','첫 번째: 키보드 닫힘.\n두 번째: 상세 대신 탭이 종료됐다.')],after=[('5','읽기는 바로, 편집은 버튼으로','기본은 키보드 없이 본다.\n「편집」을 누르면 키보드가 열린다.'),('6','뒤로가기는 현재 화면부터 닫는다','읽는 중: 상세 → 보드.\n편집 중: 키보드 → 상세 → 보드.')],foot='제안: 본문·손글씨 좌표는 보존하고 열람/편집 상태와 뒤로가기 순서만 정리한다. 이 장면은 손글씨 없는 메모다.')]

def marks(items,side):
 return ''.join(f'<div class="marker {"dashed" if side=="as" and n==4 else ""} {"right" if x<8 else ""}" style="left:{x}%;top:{y}%;width:{w}%;height:{h}%"><span class="badge">{n}</span></div>' for n,x,y,w,h in items)

def screen(i,mode,annotate=True):
 key=scenes[i]['key']; source=f'{key}-asis.png' if mode=='as' or i!=2 else 'c-background.png'
 layers=''
 if mode=='to':
  if i==0:
   layers='<div class="layer selection-actions"><button class="pillbutton primary">✎ 편집</button><button class="pillbutton">↔ 이동</button><button class="pillbutton" style="padding:0 14px">⋯</button></div><button class="layer pillbutton expand" style="left:94px;top:398px">↗</button><button class="layer pillbutton expand" style="left:243px;top:482px">↗</button>'
  elif i==1:
   layers='<div class="layer edit-area"><section class="paper"><header class="paper-head"><strong>새 메모</strong><button class="pillbutton primary">완료</button></header><div class="input-title"><span class="caret"></span>무슨 생각이 드나요?</div><p class="placeholder">내용을 적어보세요</p><div class="hint">입력한 내용은 자동으로 저장돼요</div></section></div>'
  else:
   paragraphs=''.join(f'<p>QA line {j}. Scroll this long memo with the keyboard open. Keep the caret and close button visible.</p>' for j in range(1,9))
   layers=f'<div class="layer read-area"><section class="paper"><header class="paper-head read-head"><button class="pillbutton">‹ 보드</button><button class="pillbutton primary">편집</button></header><div class="reading"><h3>QA-mobile-20261111</h3>{paragraphs}</div><div class="read-status">읽기 · 내용은 그대로</div></section></div>'
 return f'<div class="device"><img src="../screens/{source}">{layers}{marks(asmarks[i] if mode=="as" else tomarks[i],mode) if annotate else ""}</div>'

board_css='''body{background:#f4f3ee}.board{width:1840px;height:1240px;padding:32px;display:flex;flex-direction:column;gap:22px}.eyebrow{font-size:16px;color:#687267;font-weight:700;letter-spacing:.03em}h1{font-size:34px;margin:8px 0 8px;letter-spacing:-.025em}.action{font-size:19px;color:#697166}.columns{display:flex;gap:32px}.column{width:872px;flex:none}.tag{height:40px;display:flex;align-items:center;gap:12px;font-size:18px;color:#687267}.tag b{font-size:15px;padding:7px 13px;border-radius:50px;background:#e0e0d7;color:#4d5148}.tag.to b{color:white;background:#36563c}.scene{padding:24px 32px;display:flex;gap:44px;align-items:flex-start;background:#e7e9e2;border:1px solid #d9ddd2;border-radius:22px}.notes{flex:1;padding-top:48px}.note{background:#fffdf7;border:1px solid #d6dccf;border-radius:16px;padding:22px 20px;margin:0 0 22px;min-height:170px}.note strong{font-size:23px;line-height:1.45;display:block;letter-spacing:-.035em}.note strong span{display:inline-flex;align-items:center;justify-content:center;width:27px;height:27px;font-size:15px;background:#ba4f42;color:#fff;border-radius:50%;margin-bottom:12px}.note p{font-size:19px;line-height:1.65;color:#5c6657;margin:12px 0 0;white-space:pre-line;word-break:keep-all}.mini-foot{font-size:16px;line-height:1.7;color:#7b8275;padding:4px 6px}.foot{font-size:18px;line-height:1.6;color:#646e5e}.device{box-shadow:0 4px 18px #1c322015;flex:none}.legend{margin-top:12px;color:#515d4b;font-size:18px;padding-left:6px}.compare-divider{position:absolute;left:910px;top:570px;font-size:30px;color:#7b8573}'''
for i,s in enumerate(scenes):
 for mode in ['as','to']:
  file=ROOT/'board'/f'{s["key"]}-{mode}-screen.html'
  file.write_text(f'<!doctype html><html lang="ko"><meta charset="utf-8"><style>{css}</style><body class="screen-only">{screen(i,mode,False)}</body></html>')
 cols=''
 for mode in ['as','to']:
  notes=s['before' if mode=='as' else 'after']
  boxes=''.join(f'<div class="note"><strong><span>{n}</span><br>{head}</strong><p>{body}</p></div>' for n,head,body in notes)
  tail='실기기 캡처 · Android 13<br>운영 화면 / 2026.11.11' if mode=='as' else '미구현 제안 · 확정 전<br>변경 부분만 HTML로 구성'
  cols+=f'<section class="column"><div class="tag {"to" if mode=="to" else ""}"><b>{"AS-IS" if mode=="as" else "TO-BE"}</b>{"현재 · 실제 기기 화면" if mode=="as" else "제안 · 아직 구현하지 않음"}</div><div class="scene">{screen(i,mode)}<aside class="notes">{boxes}<div class="mini-foot">{tail}</div></aside></div></section>'
 out=f'<!doctype html><html lang="ko"><meta charset="utf-8"><title>Moss 모바일 · {s["title"]}</title><style>{css}{board_css}</style><body><main class="board"><header><div class="eyebrow">MOSS MOBILE / 장면 {i+1} OF 3</div><h1>{s["title"]}</h1><div class="action">{s["action"]}</div></header><div class="columns">{cols}</div><footer class="foot">{s["foot"]}<br>AS-IS는 실기기 근거입니다. TO-BE의 효과는 아직 검증하지 않았습니다.</footer></main></body></html>'
 (ROOT/'board'/f'{s["key"]}.html').write_text(out)
# Keep both renderer input specs for reuse. Individual to-screen captures are rendered next.
for mode,kind in [('as','AS-IS'),('to','TO-BE')]:
 spec={'kind':kind,'title':'Moss 모바일 · 편집 진입과 종료','subtitle':'탭은 선택 · 편집은 명시적으로 · 키보드 위 완료 · 상세에서 뒤로가기','scenes':[],'legend':[],'footnote':'AS-IS: 운영 Android 실기기 캡처. TO-BE: 미구현 제안. QA 메모와 시안의 안내 문구는 예시.'}
 for i,s in enumerate(scenes):
  spec['scenes'].append({'label':f'{s["key"].upper()}. '+['기존 할 일 편집','새 메모 입력','상세 읽기·복귀'][i],'source':'real' if mode=='as' else 'mock','image':f'screens/{s["key"]}-'+('asis.png' if mode=='as' else 'tobe.png'),'marks':[dict(n=n,x=x,y=y,w=w,h=h,side='left') for n,x,y,w,h in (asmarks if mode=='as' else tomarks)[i]]})
  for n,head,body in s['before' if mode=='as' else 'after']:
   spec['legend'].append({'n':int(n),'title':head,'body':body.replace('\n',' ')})
 (ROOT/('asis.json' if mode=='as' else 'tobe.json')).write_text(json.dumps(spec,ensure_ascii=False,indent=2))
